const colores = ['#ff3d7f', '#fcb51d', '#f8adbc', '#fc3d62', '#ffffff'];

// textura de brillo circular (se crea por código)
const texturas = colores.map((c) => {
	const cv = document.createElement('canvas');
	cv.width = cv.height = 64;
	const g = cv.getContext('2d');
	const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	grad.addColorStop(0, '#ffffff');
	grad.addColorStop(0.25, c);
	grad.addColorStop(1, 'rgba(0,0,0,0)');
	g.fillStyle = grad;
	g.fillRect(0, 0, 64, 64);
	return new THREE.CanvasTexture(cv);
});

const grupo = this;
const particulas = [];
let siguienteEstallido = 1;
let siguienteChispa = 0;
let ultimo = 0;

function crear(x, z, vx, vz, vida, tam) {
	if (particulas.length > 90) return;
	const mat = new THREE.SpriteMaterial({
		map: texturas[Math.floor(Math.random() * texturas.length)],
		blending: THREE.AdditiveBlending,
		transparent: true,
		depthWrite: false
	});
	const s = new THREE.Sprite(mat);
	s.position.set(x, 0, z);
	s.scale.set(tam, tam, 1);
	grupo.add(s);
	particulas.push({ s, vx, vz, vida, max: vida, tam });
}

function estallido() {
	const n = 22;
	const cx = (Math.random() - 0.5) * 0.5;
	const cz = (Math.random() - 0.5) * 0.3;
	for (let i = 0; i < n; i++) {
		const a = (i / n) * Math.PI * 2;
		const v = 0.35 + Math.random() * 0.25;
		crear(cx, cz, Math.cos(a) * v, Math.sin(a) * v, 1.1 + Math.random() * 0.6, 0.09);
	}
}

function chispa() {
	const a = Math.random() * Math.PI * 2;
	const r = 0.35 + Math.random() * 0.2;
	crear(Math.cos(a) * r, Math.sin(a) * r * 0.9 + 0.3,
		Math.cos(a) * 0.05, -0.12, 0.9 + Math.random() * 0.5, 0.05);
}

function update(event) {
	const t = event.time / 1000;
	const dt = Math.min(t - ultimo, 0.05);
	ultimo = t;

	if (t > siguienteEstallido) {
		estallido();
		siguienteEstallido = t + 2 + Math.random() * 1.5;
	}
	if (t > siguienteChispa) {
		chispa();
		siguienteChispa = t + 0.12;
	}

	for (let i = particulas.length - 1; i >= 0; i--) {
		const p = particulas[i];
		p.vida -= dt;
		if (p.vida <= 0) {
			grupo.remove(p.s);
			p.s.material.dispose();
			particulas.splice(i, 1);
			continue;
		}
		p.vz += 0.25 * dt; // cae suave (en tu escena abajo es +Z)
		p.s.position.x += p.vx * dt;
		p.s.position.z += p.vz * dt;
		const k = p.vida / p.max;
		p.s.material.opacity = k;
		p.s.scale.set(p.tam * (0.5 + k), p.tam * (0.5 + k), 1);
	}
}

