const verdes = [['#43b05a', '#1f7a35'], ['#5cc46d', '#2a8f40'], ['#2e9e4a', '#176b2c']];

// textura de hoja dibujada por código
const texturas = verdes.map(([claro, oscuro]) => {
	const cv = document.createElement('canvas');
	cv.width = cv.height = 128;
	const g = cv.getContext('2d');
	const grad = g.createLinearGradient(20, 108, 108, 20);
	grad.addColorStop(0, oscuro);
	grad.addColorStop(1, claro);
	g.fillStyle = grad;
	g.beginPath();
	g.moveTo(16, 112);
	g.bezierCurveTo(10, 50, 60, 10, 112, 16);
	g.bezierCurveTo(118, 70, 70, 118, 16, 112);
	g.fill();
	g.strokeStyle = 'rgba(255,255,255,0.45)';
	g.lineWidth = 3;
	g.beginPath();
	g.moveTo(12, 116);
	g.quadraticCurveTo(60, 60, 108, 20);
	g.stroke();
	return new THREE.CanvasTexture(cv);
});

const grupo = this;
const hojas = [];
const zInicio = -1.8;   // arriba del panda
const zFin = 0.55;      // borde inferior de la etiqueta
const zDesvanece = 0.45; // distancia final donde se desvanece
let siguiente = 0;
let ultimo = 0;

function crear(z) {
	if (hojas.length >= 7) return;
	const mat = new THREE.SpriteMaterial({
		map: texturas[Math.floor(Math.random() * texturas.length)],
		transparent: true,
		depthWrite: false
	});
	const s = new THREE.Sprite(mat);
	const tam = 0.09 + Math.random() * 0.07;
	const x0 = -0.35 + (Math.random() - 0.5) * 1.2;	
	s.scale.set(tam, tam, 1);
	s.position.set(x0, (Math.random() - 0.5) * 0.04, z);
	grupo.add(s);
	hojas.push({
		s, x0, z,
		vel: 0.28 + Math.random() * 0.16,
		amp: 0.05 + Math.random() * 0.07,
		freq: 0.8 + Math.random() * 0.8,
		fase: Math.random() * 6.28,
		giro: (Math.random() - 0.5) * 0.5,
		edad: 0
	});
}

// algunas hojas ya cayendo al empezar
crear(-1.2); crear(-0.6); crear(0);

function update(event) {
	const t = event.time / 1000;
	const dt = Math.min(t - ultimo, 0.05);
	ultimo = t;

	if (t > siguiente) {
		crear(zInicio);
		siguiente = t + 1.2 + Math.random() * 1.8;
	}

	for (let i = hojas.length - 1; i >= 0; i--) {
		const h = hojas[i];
		h.edad += dt;
		h.z += h.vel * dt;

		if (h.z >= zFin) {
			grupo.remove(h.s);
			h.s.material.dispose();
			hojas.splice(i, 1);
			continue;
		}

		h.s.position.z = h.z;
		h.s.position.x = h.x0 + Math.sin(h.edad * h.freq + h.fase) * h.amp;
		h.s.material.rotation = Math.sin(h.edad * h.freq + h.fase) * 0.7 + h.giro * h.edad;

		const entra = Math.min(1, h.edad / 0.6);
		const sale = Math.min(1, (zFin - h.z) / zDesvanece);
		h.s.material.opacity = entra * sale;
	}
}

