const cx = -0.35;                          // centro horizontal (el del panda)
const radio = 0.6;                         // qué tan ancho es el lazo
const tilt = THREE.MathUtils.degToRad(18); // inclinación para verse como elipse
const zAbajo = 0.55;                       // borde inferior de la etiqueta
const zArriba = -0.85;                     // altura de la cadera del panda
const duracion = 3.2;                      // segundos que tarda en subir
const pausa = 1.3;                         // descanso entre subidas
const N = 44;                              // puntos de luz por lazo

function glow(color) {
	const cv = document.createElement('canvas');
	cv.width = cv.height = 64;
	const g = cv.getContext('2d');
	const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
	grad.addColorStop(0, '#ffffff');
	grad.addColorStop(0.3, color);
	grad.addColorStop(1, 'rgba(0,0,0,0)');
	g.fillStyle = grad;
	g.fillRect(0, 0, 64, 64);
	return new THREE.CanvasTexture(cv);
}

const suave = (x) => x * x * (3 - 2 * x);

const definiciones = [
	{ color: '#ff4f9a', fase: 0,   vel: 4.5, dir: 1,  offset: 0 },
	{ color: '#ffd23f', fase: 2.5, vel: 3.8, dir: -1, offset: 1.6 }
];

const anillos = definiciones.map((d) => {
	const tex = glow(d.color);
	const grupo = new THREE.Group();
	grupo.rotation.x = tilt;
	this.add(grupo);
	const sprites = [];
	for (let i = 0; i < N; i++) {
		const mat = new THREE.SpriteMaterial({
			map: tex,
			blending: THREE.AdditiveBlending,
			transparent: true,
			depthWrite: false,
			depthTest: true
		});
		const s = new THREE.Sprite(mat);
		s.renderOrder = 10;
		grupo.add(s);
		sprites.push(s);
	}
	return { d, grupo, sprites };
});

function update(event) {
	const t = event.time / 1000;
	const ciclo = duracion + pausa;

	anillos.forEach((a) => {
		const local = (t + a.d.offset) % ciclo;
		if (local > duracion) { a.grupo.visible = false; return; }
		a.grupo.visible = true;

		const p = local / duracion;                       // 0 a 1
		const frena = 1 - (1 - p) * (1 - p);              // sube y va frenando al final
		const z = zAbajo + (zArriba - zAbajo) * frena;
		a.grupo.position.set(cx, 0, z);

		const entra = suave(Math.min(1, p / 0.2));         // aparece en el primer 20%
		const sale = suave(Math.min(1, (1 - p) / 0.55));   // se desvanece en el último 55%
		const envolvente = entra * sale;

		const cabeza = t * a.d.vel * a.d.dir + a.d.fase;

		for (let i = 0; i < N; i++) {
			const ang = cabeza - a.d.dir * i * 0.075;
			const x = Math.cos(ang) * radio;
			const y = Math.sin(ang) * radio;
			const frente = y > 0 ? 1 : 0.45;              // la parte de atrás se ve más tenue
			const cola = Math.pow(1 - i / N, 1.4);
			const s = a.sprites[i];
			s.position.set(x, y, 0);
			s.material.opacity = envolvente * cola * frente;
			const tam = 0.12 * (0.5 + 0.5 * envolvente) * (1 - 0.7 * i / N);
			s.scale.set(tam, tam, 1);
		}
	});
}

