	const cv = document.createElement('canvas');
	cv.width = w; cv.height = h;
	dibujar(cv.getContext('2d'), w, h);
	return new THREE.CanvasTexture(cv);
}

// gota: cabeza redonda arriba y cola fina abajo
function gota(c1, c2) {
	return textura(64, 128, (c, w, h) => {
		const gr = c.createLinearGradient(0, 0, 0, h);
		gr.addColorStop(0, c1);
		gr.addColorStop(1, c2);
		c.fillStyle = gr;
		c.beginPath();
		c.moveTo(w / 2, h - 4);
		c.bezierCurveTo(w * 0.98, h * 0.55, w * 0.98, 4, w / 2, 4);
		c.bezierCurveTo(w * 0.02, 4, w * 0.02, h * 0.55, w / 2, h - 4);
		c.fill();
	});
}

// media luna (confeti)
function creciente(color) {
	return textura(64, 64, (c) => {
		c.fillStyle = color;
		c.beginPath();
		c.arc(32, 32, 24, 0, Math.PI * 2);
		c.fill();
		c.globalCompositeOperation = 'destination-out';
		c.beginPath();
		c.arc(42, 26, 20, 0, Math.PI * 2);
		c.fill();
	});
}

function corazon(color) {
	return textura(64, 64, (c) => {
		c.fillStyle = color;
		c.beginPath();
		c.moveTo(32, 56);
		c.bezierCurveTo(4, 36, 6, 10, 24, 10);
		c.bezierCurveTo(30, 10, 32, 16, 32, 18);
		c.bezierCurveTo(32, 16, 34, 10, 40, 10);
		c.bezierCurveTo(58, 10, 60, 36, 32, 56);
		c.fill();
	});
}

// ---------- COLORES (paleta Té de Lichi) ----------
const gotas = [
	gota('#fc3d62', '#ff8aa0'),
	gota('#ff6f8a', '#ffd0da'),
	gota('#f8adbc', '#fff1f4'),
	gota('#e8244f', '#fc3d62')
];
const crecientes = [
	creciente('#fc3d62'), creciente('#ff6f8a'), creciente('#f8adbc'),
	creciente('#fff1f4'), creciente('#e8244f')
];
const corazones = [corazon('#fc3d62'), corazon('#ff6f8a'), corazon('#f8adbc')];

const parts = [];
let siguiente = 0.8;
let ultimo = 0;

function crear(tipo, ang, v) {
	const mat = new THREE.SpriteMaterial({
		map: tipo === 'gota' ? elige(gotas) : elige(corazones),
		transparent: true,
		depthWrite: false
	});
	const s = new THREE.Sprite(mat);
	grupo.add(s);
	parts.push({
		s, tipo,
		x: (Math.random() - 0.5) * 0.1, z: 0,
		vx: Math.sin(ang) * v,
		vu: Math.cos(ang) * v,            // vu = velocidad hacia arriba
		edad: 0,
		vida: tipo === 'gota' ? 2.0 + Math.random() * 0.5 : 1.8 + Math.random() * 0.5,
		ancho: tipo === 'gota' ? 0.08 + Math.random() * 0.06 : 0.12 + Math.random() * 0.05,
		giro: (Math.random() - 0.5) * 6,
		fase: Math.random() * 6.28,
		convertido: false
	});
}

function estallido() {
	[-1, 1].forEach((lado) => {
		for (let i = 0; i < 6; i++) {
			const ang = lado * (30 + i * 10 + Math.random() * 6) * Math.PI / 180;
			crear('gota', ang, 1.3 + Math.random() * 0.7);
		}
	});
	for (let i = 0; i < 3; i++) {
		const lado = Math.random() < 0.5 ? -1 : 1;
		crear('corazon', lado * (0.4 + Math.random() * 0.7), 0.5 + Math.random() * 0.4);
	}
}

function update(event) {
	const t = event.time / 1000;
	const dt = Math.min(t - ultimo, 0.05);
	ultimo = t;

	if (t > siguiente) {
		estallido();
		siguiente = t + 3.6 + Math.random() * 1.2;
	}

	for (let i = parts.length - 1; i >= 0; i--) {
		const p = parts[i];
		p.edad += dt;
		const f = p.edad / p.vida;

		if (f >= 1) {
			grupo.remove(p.s);
			p.s.material.dispose();
			parts.splice(i, 1);
			continue;
		}

		if (p.tipo === 'gota') {
			if (f < 0.5) {
				// sale disparada, frena y se encoge
				const drag = Math.exp(-2.4 * dt);
				p.vx *= drag;
				p.vu = p.vu * drag - 0.25 * dt;
				const vel = Math.hypot(p.vx, p.vu);
				p.s.material.rotation = Math.atan2(p.vu, p.vx) - Math.PI / 2;
				const crece = acota(p.edad / 0.12);
				const m = 1 - 0.75 * suave(acota((f - 0.28) / 0.22));
				const largo = p.ancho * (1.2 + Math.min(vel, 1.5) * 1.6);
				p.s.scale.set(p.ancho * (0.6 + 0.4 * crece) * m, largo * crece * m, 1);
				p.s.material.opacity = 1;
			} else {
				// se convierte en confeti: cae, gira y se desvanece
				if (!p.convertido) {
					p.convertido = true;
					p.s.material.map = elige(crecientes);
					p.vx *= 0.3;
					p.vu *= 0.3;
				}
				const q = (f - 0.5) / 0.5;
				p.vu -= gravedad * dt;
				p.vx += Math.sin(p.edad * 5 + p.fase) * 0.4 * dt;
				p.s.material.rotation += p.giro * dt;
				const tam = 0.06 * (1 - 0.3 * q);
				p.s.scale.set(tam, tam, 1);
				p.s.material.opacity = 1 - suave(q);
			}
		} else {
			// corazón: aparece, flota y se desvanece
			const drag = Math.exp(-1.8 * dt);
			p.vx = p.vx * drag + Math.sin(p.edad * 3 + p.fase) * 0.2 * dt;
			p.vu = p.vu * drag + 0.15 * dt;
			const crece = acota(p.edad / 0.25);
			const fin = suave(acota((f - 0.5) / 0.5));
			const tam = p.ancho * (0.3 + 0.7 * crece) * (1 - 0.6 * fin);
			p.s.scale.set(tam, tam, 1);
			p.s.material.rotation = Math.sin(p.edad * 3 + p.fase) * 0.3;
			p.s.material.opacity = 1 - suave(acota((f - 0.6) / 0.4));
		}

		p.x += p.vx * dt;
		p.z -= p.vu * dt;   // arriba es -Z en tu escena
		p.s.position.set(p.x, 0, p.z);
	}
}

