const fruta = this;
const baseZ = this.position.z;
const baseSX = this.scale.x;
const baseSY = this.scale.y;

const ciclo = 4.0;       // cada cuántos segundos pasa el brillo
const brilloDur = 0.9;   // lo que tarda en cruzar

let cv = null, ctx = null, tex = null, img = null, overlay = null;
const W = 256;
let H = 256;

function crearBrillo() {
	img = fruta.material.map && fruta.material.map.image;
	if (!img) return false;
	const iw = img.naturalWidth || img.width;
	const ih = img.naturalHeight || img.height;
	if (!iw || !ih) return false;
	H = Math.round(W * ih / iw);
	cv = document.createElement('canvas');
	cv.width = W;
	cv.height = H;
	ctx = cv.getContext('2d');
	tex = new THREE.CanvasTexture(cv);
	overlay = new THREE.Sprite(new THREE.SpriteMaterial({
		map: tex,
		blending: THREE.AdditiveBlending,
		transparent: true,
		depthWrite: false,
		depthTest: false
	}));
	overlay.renderOrder = 11;
	overlay.visible = false;
	if (fruta.parent) fruta.parent.add(overlay);
	return true;
}

function dibujarBrillo(c) {
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, W, H);
	ctx.save();
	ctx.translate(c * W, H / 2);
	ctx.rotate(0.35);
	const bw = W * 0.22;
	const g = ctx.createLinearGradient(-bw / 2, 0, bw / 2, 0);
	g.addColorStop(0, 'rgba(255,255,255,0)');
	g.addColorStop(0.5, 'rgba(255,255,255,0.95)');
	g.addColorStop(1, 'rgba(255,255,255,0)');
	ctx.fillStyle = g;
	ctx.fillRect(-bw / 2, -H, bw, H * 2);
	ctx.restore();
	// se queda solo con la parte que cae sobre la fruta
	ctx.globalCompositeOperation = 'destination-in';
	ctx.drawImage(img, 0, 0, W, H);
	ctx.globalCompositeOperation = 'source-over';
	tex.needsUpdate = true;
}

function update(event) {
	const t = event.time / 1000;
	const local = t % ciclo;

	// Flotar suave
	this.position.z = baseZ + Math.sin(t * 1.6 + 1) * 0.025;
	const pulso = 1 + Math.sin(t * 2.2 + 1) * 0.025;
	this.scale.x = baseSX * pulso;
	this.scale.y = baseSY * pulso;
	this.material.rotation = Math.sin(t * 1.2 + 1) * 0.04;

	// Brillo que cruza la fruta
	if (!overlay && !crearBrillo()) return; // espera a que cargue la imagen
	if (local <= brilloDur) {
		const s = local / brilloDur;
		dibujarBrillo(-0.2 + 1.4 * s);
		overlay.visible = true;
		overlay.position.set(this.position.x, this.position.y + 0.01, this.position.z);
		overlay.scale.set(this.scale.x, this.scale.y, 1);
		overlay.material.rotation = this.material.rotation;
	} else {
		overlay.visible = false;
	}
}
